#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;

    void report() {
        cout << name << " 今天吃了 " << fish << " 条小鱼干喵" << endl;
    }
};

int main() {
    string name;
    int fish = 0;
    cin >> name >> fish;

    Cat c1;
    c1.name = name;
    c1.fish = fish;
    c1.report();
    return 0;
}

