    int a = 0;
    int b = 0;
    cin >> a >> b;

    Cat c1;
    Cat c2;
    c1.name = "小橘";
    c1.fish = a;
    c2.name = "狸花";
    c2.fish = b;

    c1.greet();
    c2.greet();
    return 0;
}

